import { readFileSync } from 'node:fs'

const files = {
  performance: 'crates/mlt_rules/src/performance/mod.rs',
  readability: 'crates/mlt_rules/src/readability/mod.rs',
}

function moduleDocstring(file: string): string {
  const lines = readFileSync(file, 'utf8').split('\n')
  const out: string[] = []
  for (const ln of lines) {
    const m = ln.match(/^\s*\/\/!(.*)$/)
    if (!m) break
    out.push(m[1].replace(/^ /, ''))
  }
  return out.join('\n')
}

function parseFrontMatter(doc: string): Record<string, string> | null {
  const lines = doc.split('\n')
  let i = lines.findIndex((l) => l.trim() === '```mlt')
  if (i === -1) return null
  const kv: Record<string, string> = {}
  for (let j = i + 1; j < lines.length; j++) {
    const l = lines[j].trim()
    if (l === '```') break
    const m = l.match(/^([A-Za-z_]+)\s*=\s*(.+)$/)
    if (!m) continue
    let v = m[2].trim()
    if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) {
      v = v.slice(1, -1)
    }
    kv[m[1]] = v
  }
  return kv.id ? kv : null
}

function splitSections(doc: string): Array<{ heading: string; body: string[] }> {
  const lines = doc.split('\n')
  const fmEnd = lines.findIndex((l) => l.trim() === '```mlt')
  let start = 0
  if (fmEnd !== -1) {
    start = fmEnd
    for (let j = fmEnd + 1; j < lines.length; j++) {
      if (lines[j].trim() === '```') { start = j + 1; break }
    }
  }
  const sections: Array<{ heading: string; body: string[] }> = []
  let cur: { heading: string; body: string[] } | null = null
  for (let j = start; j < lines.length; j++) {
    const l = lines[j]
    if (l.startsWith('## ')) {
      if (cur) sections.push(cur)
      cur = { heading: l.slice(3).trim(), body: [] }
    } else if (cur) {
      cur.body.push(l)
    }
  }
  if (cur) sections.push(cur)
  return sections
}

function splitTableRow(line: string): string[] {
  const cells: string[] = []
  let current = ''
  let prevBackslash = false
  for (const ch of line) {
    if (ch === '|' && !prevBackslash) {
      cells.push(current.trim()); current = ''
    } else { current += ch }
    prevBackslash = ch === '\\'
  }
  cells.push(current.trim())
  return cells
}

function parseCheckTable(lines: string[]): Array<{id: string, severity: string, fix: boolean, description: string}> {
  const rows: Array<{id: string, severity: string, fix: boolean, description: string}> = []
  let inHeader = false
  for (const raw of lines) {
    const l = raw.trim()
    if (!l.startsWith('|')) continue
    let cells = splitTableRow(l)
    if (cells.length && cells[0] === '') cells = cells.slice(1)
    if (cells.some((c) => c.includes('Check ID'))) { inHeader = true; continue }
    if (inHeader && cells.every((c) => /^:?-{2,}:?$/.test(c.trim()))) continue
    if (!inHeader) continue
    const id = (cells[0] ?? '').replace(/[` ]/g, '')
    if (!/^[A-Za-z][A-Za-z0-9._]*$/.test(id)) continue
    const severity = (cells[1] ?? 'warning').trim().toLowerCase()
    const fix = (cells[2] ?? 'no').trim().toLowerCase().startsWith('y')
    const description = (cells[3] ?? '').trim()
    rows.push({ id, severity, fix, description })
  }
  return rows
}

function sectionBody(sections: Array<{heading: string; body: string[]}>, heading: string): string | null {
  const s = sections.find((x) => x.heading === heading)
  if (!s) return null
  const text = s.body.join('\n').replace(/^\n+|\n+$/g, '')
  return text.length ? text : null
}

for (const [name, path] of Object.entries(files)) {
  const doc = moduleDocstring(path)
  const fm = parseFrontMatter(doc)
  if (!fm) { console.error(`${name}: NO FRONTMATTER`); process.exit(1) }
  const sections = splitSections(doc)
  const table = sectionBody(sections, 'Check IDs')
  if (!table) { console.error(`${name}: NO Check IDs section`); process.exit(1) }
  const rows = parseCheckTable(table.split('\n'))
  const fixSection = sectionBody(sections, 'Fix')
  const examples = sectionBody(sections, 'Examples')
  const rule = sectionBody(sections, 'Rule')
  const config = sectionBody(sections, 'Configuration')

  console.log(`\n=== ${name} ===`)
  console.log(`frontmatter:`, JSON.stringify(fm))
  console.log(`fix flag: ${fm.fix} (has ## Fix section: ${fixSection !== null})`)
  console.log(`has ## Rule: ${rule !== null}`)
  console.log(`has ## Examples: ${examples !== null}`)
  console.log(`has ## Configuration: ${config !== null}`)
  console.log(`check rows: ${rows.length}`)
  for (const r of rows) console.log(`  ${r.id}\t${r.severity}\tfix=${r.fix}\t${r.description}`)

  // Validate required sections
  const errs: string[] = []
  if (!rule) errs.push('missing ## Rule')
  if (!examples) errs.push('missing ## Examples')
